#!/bin/bash
sed -i 's/val w = layer.width.toInt().coerceIn(1, 2048)/val pad = 60\n                val w = layer.width.toInt().coerceIn(1, 2048)\n                val pw = w + pad * 2/g' app/src/main/java/com/example/studio/ui/WorkspaceScreen.kt
sed -i 's/val h = layer.height.toInt().coerceIn(1, 2048)/val h = layer.height.toInt().coerceIn(1, 2048)\n                val ph = h + pad * 2/g' app/src/main/java/com/example/studio/ui/WorkspaceScreen.kt
sed -i 's/val cacheKey = "adj_shape_${layer.id}_${w}_${h}_${finalColor.hashCode()}_${activeList.hashCode()}"/val cacheKey = "adj_shape_${layer.id}_${pw}_${ph}_${finalColor.hashCode()}_${activeList.hashCode()}"/g' app/src/main/java/com/example/studio/ui/WorkspaceScreen.kt
sed -i 's/val offscreen = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)/val offscreen = android.graphics.Bitmap.createBitmap(pw, ph, android.graphics.Bitmap.Config.ARGB_8888)/g' app/src/main/java/com/example/studio/ui/WorkspaceScreen.kt
sed -i 's/c.drawRect(0f, 0f, w.toFloat(), h.toFloat(), p)/c.translate(pad.toFloat(), pad.toFloat())\n                        val pathObj = layerPath.asAndroidPath()\n                        if (pathObj.isEmpty) {\n                            c.drawRect(0f, 0f, w.toFloat(), h.toFloat(), p)\n                        } else {\n                            c.drawPath(pathObj, p)\n                        }/g' app/src/main/java/com/example/studio/ui/WorkspaceScreen.kt
